import asyncio
import json
import sys
def normalize(values):
    if not isinstance(values, list) or not all(isinstance(value, int) and not isinstance(value, bool) for value in values):
        raise ValueError('values must be integer list')
    return sorted(set(values))
async def summarize(text):
    values = normalize(json.loads(text)['scores'])
    await asyncio.sleep(0)
    return {'count': len(values), 'passed': sum(value >= 60 for value in values), 'total': sum(values)}
text = sys.stdin.read().strip()
if text == '__invalid__':
    raise ValueError('reserved invalid marker')
print(json.dumps(asyncio.run(summarize(text)), sort_keys=True))
